<?php require dirname(__DIR__).'/includes/functions.php'; $a=require_admin(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') { check_csrf(); try { rate_limit('admin-password',10); if(!password_verify(post('current_password'),$a['password'])) throw new DomainException('Current password is incorrect.'); $p=password_value(post('password')); if($p!==post('confirm_password')) throw new DomainException('Passwords do not match.'); if(password_verify($p,$a['password'])) throw new DomainException('Choose a new password.'); $hash=password_hash($p,PASSWORD_DEFAULT); q('UPDATE admins SET password=?,must_change_password=0 WHERE id=?',[$hash,$a['id']]); $_SESSION['admin_auth']=hash('sha256',$hash); session_regenerate_id(true); flash('Admin password updated.'); go('admin/index.php'); } catch(DomainException $ex) { $error=$ex->getMessage(); } }
$title='Change password'; require __DIR__.'/_header.php'; ?>
<div class="glass auth-card"><?php if($a['must_change_password']): ?><p class="alert alert-warning">Change the installation password before managing your store.</p><?php endif; ?><form method="post"><?= csrf() ?><?php foreach(['current_password'=>'Current password','password'=>'New password (10–72 characters)','confirm_password'=>'Confirm new password'] as $key=>$label): ?><label><?= $label ?><input name="<?= $key ?>" type="password" maxlength="72" autocomplete="<?= $key==='current_password'?'current-password':'new-password' ?>" class="form-control" required></label><?php endforeach; ?><button class="btn btn-accent">Update password</button></form></div><?php require __DIR__.'/_footer.php'; ?>
